import { isRecord } from "./is-record.js";
export function isJsonValue(value) {
    if (value === null || typeof value === "string" || typeof value === "boolean") {
        return true;
    }
    if (typeof value === "number") {
        return Number.isFinite(value);
    }
    if (Array.isArray(value)) {
        return value.every(isJsonValue);
    }
    return isRecord(value) && Object.values(value).every(isJsonValue);
}
/**
 * `JSON.parse`, checked as {@link JsonValue}. Invalid JSON still throws.
 * A successful parse is JSON, so the check only rejects values JSON cannot
 * produce.
 */
export function parseJsonValue(text) {
    const parsed = JSON.parse(text);
    if (!isJsonValue(parsed)) {
        throw new SyntaxError("parsed value is not JSON");
    }
    return parsed;
}
/**
 * JSON form of a value, for a store that only accepts {@link JsonValue}.
 * Drops `undefined` fields the same way `JSON.stringify` does.
 */
export function storedJson(value) {
    const text = JSON.stringify(value ?? null);
    const parsed = JSON.parse(text);
    if (!isJsonValue(parsed)) {
        throw new SyntaxError("value is not JSON");
    }
    return parsed;
}
/** JSON object, or `undefined` when the text is not one. Invalid JSON throws. */
export function parseJsonRecord(text) {
    const parsed = JSON.parse(text);
    return isRecord(parsed) ? parsed : undefined;
}
/** Session events are JSON objects with a string `type`. */
export function isSessionEvent(value) {
    return isRecord(value) && typeof value.type === "string";
}
/** One NDJSON line, or `undefined` when it is not a session event. */
export function parseSessionEventLine(text) {
    try {
        const parsed = JSON.parse(text);
        return isSessionEvent(parsed) ? parsed : undefined;
    }
    catch {
        return undefined;
    }
}
